To solve the longest increasing subsequence problem using dynamic programming, you can use the following Python program:

<python>
def longest_increasing_subsequence(seq):
    n = len(seq)
    lis = [1] * n

    for i in range(1, n):
        for j in range(i):
            if seq[i] > seq[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    return max(lis)

# Input sequence
sequence = [3, 10, 2, 1, 20]

# Calculate the length of the longest increasing subsequence
longest_increasing_subsequence(sequence)
